<?php
session_start();require_once __DIR__.'/../config/config.php';if(empty($_SESSION['user_id'])){header('Location:login.php');exit;}
$userId=(int)$_SESSION['user_id'];$role=$_SESSION['role']??'';if(!in_array($role,['publisher_admin','shop_admin'],true)){header('Location:home.php');exit;}
$type=$role==='publisher_admin'?'publisher':'shop';if($type==='publisher')$q=$pdo->prepare('SELECT p.publisher_id id,p.company_name name FROM publisher_staff ps JOIN publishers p ON p.publisher_id=ps.publisher_id WHERE ps.user_id=? LIMIT 1');else$q=$pdo->prepare('SELECT s.shop_id id,s.shop_name name FROM shop_staff ss JOIN shops s ON s.shop_id=ss.shop_id WHERE ss.user_id=? LIMIT 1');$q->execute([$userId]);$seller=$q->fetch(PDO::FETCH_ASSOC);if(!$seller){exit('ไม่พบร้าน');}$sellerId=(int)$seller['id'];$seller_name=$seller['name'];$active_menu='support';if(empty($_SESSION['admin_chat_csrf']))$_SESSION['admin_chat_csrf']=bin2hex(random_bytes(24));
$conversationId=(int)($_GET['conversation']??$_POST['conversation_id']??0);
if($_SERVER['REQUEST_METHOD']==='POST'&&isset($_POST['send_message'])){if(!hash_equals($_SESSION['admin_chat_csrf'],$_POST['csrf_token']??''))exit('คำขอไม่ถูกต้อง');$text=trim($_POST['message_text']??'');$q=$pdo->prepare('SELECT * FROM chat_conversations WHERE conversation_id=? AND seller_type=? AND seller_id=?');$q->execute([$conversationId,$type,$sellerId]);$conv=$q->fetch(PDO::FETCH_ASSOC);if($conv&&$text!==''){$pdo->beginTransaction();try{$pdo->prepare('INSERT INTO chat_messages(conversation_id,sender_user_id,message_text) VALUES(?,?,?)')->execute([$conversationId,$userId,$text]);$pdo->prepare('UPDATE chat_conversations SET last_message_at=NOW() WHERE conversation_id=?')->execute([$conversationId]);$pdo->prepare("INSERT INTO notifications(user_id,title,message,notification_type,chat_conversation_id,is_read,sent_via) VALUES(?,'ข้อความใหม่จากร้านค้า',?,'chat',?,0,'web')")->execute([$conv['customer_user_id'],mb_strimwidth($text,0,120,'…'),$conversationId]);$pdo->commit();}catch(Throwable $e){$pdo->rollBack();throw $e;}}header('Location:admin_chat.php?conversation='.$conversationId);exit;}
$q=$pdo->prepare("SELECT c.*,u.display_name,u.profile_image,(SELECT message_text FROM chat_messages WHERE conversation_id=c.conversation_id ORDER BY message_id DESC LIMIT 1) last_text FROM chat_conversations c JOIN users u ON u.user_id=c.customer_user_id WHERE c.seller_type=? AND c.seller_id=? ORDER BY c.last_message_at DESC,c.updated_at DESC");$q->execute([$type,$sellerId]);$threads=$q->fetchAll(PDO::FETCH_ASSOC);
$active=null;$messages=[];$book=null;if($conversationId){$q=$pdo->prepare('SELECT c.*,u.display_name FROM chat_conversations c JOIN users u ON u.user_id=c.customer_user_id WHERE c.conversation_id=? AND c.seller_type=? AND c.seller_id=?');$q->execute([$conversationId,$type,$sellerId]);$active=$q->fetch(PDO::FETCH_ASSOC);if($active){$q=$pdo->prepare('SELECT m.*,u.display_name FROM chat_messages m JOIN users u ON u.user_id=m.sender_user_id WHERE m.conversation_id=? ORDER BY m.message_id');$q->execute([$conversationId]);$messages=$q->fetchAll(PDO::FETCH_ASSOC);$pdo->prepare('UPDATE chat_messages SET is_read=1 WHERE conversation_id=? AND sender_user_id<>?')->execute([$conversationId,$userId]);if($active['referenced_book_id']){$q=$pdo->prepare('SELECT * FROM books WHERE book_id=?');$q->execute([$active['referenced_book_id']]);$book=$q->fetch(PDO::FETCH_ASSOC);}}}
if($active){$peerProfile=$pdo->prepare('SELECT profile_image FROM users WHERE user_id=?');$peerProfile->execute([(int)$active['customer_user_id']]);$active['profile_image']=$peerProfile->fetchColumn()?:null;}
$threadUnreadStmt=$pdo->prepare('SELECT COUNT(*) FROM chat_messages WHERE conversation_id=? AND is_read=0 AND sender_user_id=?');foreach($threads as &$thread){$threadUnreadStmt->execute([(int)$thread['conversation_id'],(int)$thread['customer_user_id']]);$thread['unread_count']=(int)$threadUnreadStmt->fetchColumn();}unset($thread);
function acImg(?string $v):?string{
    if(!$v)return null;
    if(preg_match('#^https?://#i',$v))return $v;
    $v=ltrim(str_replace('\\','/',$v),'/');
    if(str_starts_with($v,'pages/'))return '/'.$v;
    if(str_starts_with($v,'uploads/'))return '/pages/'.$v;
    if(str_starts_with($v,'assets/'))return '/'.$v;
    return '/assets/image/books/'.$v;
}
$adminChatError=trim((string)($_GET['error']??''));
ob_start(function(string $html) use($messages,$adminChatError,$conversationId,$active,$threads):string{
    $lastReadOwnMessageId=0;
    foreach($messages as $message){if((int)$message['sender_user_id']===(int)$_SESSION['user_id']&&(int)$message['is_read']===1)$lastReadOwnMessageId=(int)$message['message_id'];}
    $messageIndex=0;$previousDate='';
    $html=preg_replace_callback('#<div class="bubble ([^"]*)">(.*?)</div>#s',function($match)use($messages,&$messageIndex,&$previousDate,$lastReadOwnMessageId){
        $message=$messages[$messageIndex++]??null;if(!$message)return $match[0];
        $timestamp=strtotime($message['created_at']);$dateKey=date('Y-m-d',$timestamp);$divider='';
        if($dateKey!==$previousDate){$divider='<div class="chat-date-divider"><span>'.date('d/m/Y',$timestamp).'</span></div>';$previousDate=$dateKey;}
        $receipt=(int)$message['message_id']===$lastReadOwnMessageId?'<span class="read-receipt">อ่านแล้ว</span>':'';
        return $divider.'<div class="bubble '.$match[1].'" data-message-id="'.(int)$message['message_id'].'" data-date="'.$dateKey.'">'.$match[2].$receipt.'</div>';
    },$html)??$html;
    $html=str_replace('<form class="composer" method="post">','<form class="composer" id="adminChatComposer" method="post" enctype="multipart/form-data" action="/pages/handlers/admin_chat_send_message.php"><label class="admin-chat-attach" title="แนบรูปภาพหรือวิดีโอ">＋<input id="adminChatMedia" type="file" name="chat_media" accept="image/jpeg,image/png,image/webp,image/gif,video/mp4,video/webm,video/quicktime"></label>',$html);
    $html=preg_replace('#(<input name="message_text"[^>]*?)\srequired(\s[^>]*>)#','$1$2',$html,1)??$html;
    $media=array_map(fn($m)=>$m['image_path']?['url'=>'/pages/'.ltrim(str_replace('\\','/',$m['image_path']),'/'),'type'=>$m['media_type']?:'image']:null,$messages);
    $extra='<style>.composer{position:relative;align-items:center}.admin-chat-attach{width:44px;height:44px;flex:0 0 44px;border:1px solid #d18aa7;border-radius:50%;display:grid;place-items:center;color:#b85c80;font-size:25px;cursor:pointer;background:#fff}.admin-chat-attach:hover{background:#fae8ef}.admin-chat-attach input{position:absolute!important;width:1px!important;height:1px!important;opacity:0!important;pointer-events:none}.admin-media-preview{position:absolute;left:14px;bottom:72px;padding:7px;border:1px solid #e4d3da;border-radius:11px;background:#fff;box-shadow:0 5px 18px #633b4b22;z-index:6}.admin-media-preview img,.admin-media-preview video{display:block;width:130px;height:90px;object-fit:cover;border-radius:7px}.admin-media-preview button{position:absolute;right:-8px;top:-8px;width:24px;height:24px;border:0;border-radius:50%;background:#b94f62;color:#fff;cursor:pointer}.bubble .chat-media{display:block;width:min(320px,100%);max-height:360px;object-fit:cover;border-radius:10px;margin:4px 0 7px}.admin-chat-error{margin:8px 14px;padding:9px 12px;border-radius:8px;background:#fde5e3;color:#a63838;font-size:13px}</style><script>document.addEventListener("DOMContentLoaded",()=>{const media='.json_encode($media,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES).';document.querySelectorAll(".messages .bubble").forEach((bubble,index)=>{const item=media[index];if(!item)return;const element=document.createElement(item.type==="video"?"video":"img");element.className="chat-media";element.src=item.url;if(item.type==="video"){element.controls=true;element.preload="metadata";}bubble.insertBefore(element,bubble.querySelector("time"));});const input=document.getElementById("adminChatMedia"),form=document.getElementById("adminChatComposer");input?.addEventListener("change",()=>{form.querySelector(".admin-media-preview")?.remove();const file=input.files[0];if(!file)return;const box=document.createElement("div");box.className="admin-media-preview";const preview=document.createElement(file.type.startsWith("video/")?"video":"img");preview.src=URL.createObjectURL(file);if(preview.tagName==="VIDEO"){preview.muted=true;preview.controls=true;}const remove=document.createElement("button");remove.type="button";remove.textContent="×";remove.onclick=()=>{input.value="";box.remove();};box.append(preview,remove);form.append(box);});});</script>';
    if($adminChatError!=='')$html=str_replace('<div class="messages">','<div class="admin-chat-error">'.htmlspecialchars($adminChatError).'</div><div class="messages">',$html);
    $lastMessageId=$messages?(int)end($messages)['message_id']:0;
    $live='<script>window.wanawanAdminChat='.json_encode(['conversationId'=>$conversationId,'lastMessageId'=>$lastMessageId,'peerImage'=>acImg($active['profile_image']??null),'peerName'=>$active['display_name']??'ลูกค้า','threadProfiles'=>array_map(fn($thread)=>['id'=>(int)$thread['conversation_id'],'image'=>acImg($thread['profile_image']??null),'name'=>$thread['display_name']??'ลูกค้า','unread'=>(int)($thread['unread_count']??0)],$threads)],JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES).';</script><script src="/assets/js/admin-chat-live.js?v='.filemtime(__DIR__.'/../assets/js/admin-chat-live.js').'" defer></script>';
    $html=str_replace('</body>',$live.'</body>',$html);
    return str_replace('</body>',$extra.'</body>',$html);
});
?>
<!doctype html><html lang="th"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>แชตและการสนับสนุน - วนวรรณ</title><link rel="stylesheet" href="../assets/css/styles.css"><style>
*{box-sizing:border-box}body{margin:0;font-family:var(--font-family);background:#fff}.main{margin-left:260px;width:calc(100% - 260px);padding:26px 16px}.chat{height:calc(100vh - 52px);display:grid;grid-template-columns:290px 1fr 285px;border:1px solid #ccd3c5;border-radius:14px;overflow:hidden}.threads{border-right:1px solid #ccd3c5}.threads h2,.chat-head,.product h3{padding:20px;margin:0;color:var(--secondary-color);border-bottom:1px solid #ccd3c5}.search{margin:12px;padding:10px;border:1px solid #ccc;border-radius:8px;width:calc(100% - 24px);font:inherit}.thread{display:block;padding:16px;border-bottom:1px solid #eee;color:inherit;text-decoration:none}.thread.active{background:#e6f0f1}.thread small{display:block;color:var(--text-muted);margin-top:5px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.conversation{display:flex;flex-direction:column}.messages{flex:1;padding:24px;overflow:auto;background:#fbf9f7}.bubble{max-width:72%;padding:13px 16px;border:1px solid #d8d2cc;border-radius:16px;margin-bottom:14px;background:#fff}.bubble.mine{margin-left:auto;background:#d18aa7;color:#fff;border-color:#d18aa7}.bubble time{display:block;text-align:right;font-size:10px;opacity:.7}.composer{display:flex;gap:9px;padding:14px;border-top:1px solid #ddd}.composer input{flex:1;padding:12px 16px;border:1px solid #ccc;border-radius:22px;font:inherit}.composer button{width:46px;border:0;border-radius:50%;background:#d18aa7;color:#fff}.product{border-left:1px solid #ccd3c5}.product-card{margin:18px;padding:12px;border:1px solid #ccd3c5;border-radius:12px}.product-card img{width:100%;height:220px;object-fit:cover;border-radius:8px}.product-card strong{display:block;margin:10px 0;color:var(--secondary-color)}.empty{display:grid;place-items:center;color:var(--text-muted)}@media(max-width:1000px){.chat{grid-template-columns:250px 1fr}.product{display:none}}@media(max-width:800px){.main{margin:0;width:100%}.chat{grid-template-columns:1fr}.threads{display:none}}
</style></head><body><?php include __DIR__.'/../components/sidebar.php';?><main class="main"><div class="chat"><aside class="threads"><h2>ข้อความล่าสุด</h2><input class="search" placeholder="ค้นหาบทสนทนา..."><?php foreach($threads as $t):?><a class="thread <?=$conversationId==(int)$t['conversation_id']?'active':''?>" href="?conversation=<?=$t['conversation_id']?>"><strong><?=htmlspecialchars($t['display_name']?:'ลูกค้า')?></strong><small><?=htmlspecialchars($t['last_text']?:'เริ่มต้นบทสนทนา')?></small></a><?php endforeach;?></aside><?php if(!$active):?><section class="empty">เลือกบทสนทนา</section><aside class="product"></aside><?php else:?><section class="conversation"><h2 class="chat-head"><?=htmlspecialchars($active['display_name']?:'ลูกค้า')?></h2><div class="messages"><?php foreach($messages as $m):?><div class="bubble <?=$m['sender_user_id']==$userId?'mine':''?>"><?=nl2br(htmlspecialchars($m['message_text']))?><time><?=date('H:i',strtotime($m['created_at']))?></time></div><?php endforeach;?></div><form class="composer" method="post"><input type="hidden" name="csrf_token" value="<?=htmlspecialchars($_SESSION['admin_chat_csrf'])?>"><input type="hidden" name="conversation_id" value="<?=$conversationId?>"><input name="message_text" placeholder="พิมพ์ข้อความตอบ..." required autocomplete="off"><button name="send_message">➤</button></form></section><aside class="product"><h3>ข้อมูลสินค้าที่ถามถึง</h3><?php if($book):?><div class="product-card"><?php if($img=acImg($book['image_cover'])):?><img src="<?=htmlspecialchars($img)?>"><?php endif;?><strong><?=htmlspecialchars($book['title'])?></strong><span>฿<?=number_format($book['price'],2)?></span><p>คงเหลือ <?=number_format($book['stock_quantity'])?> เล่ม</p></div><?php else:?><div class="empty" style="padding:50px">บทสนทนาทั่วไป</div><?php endif;?></aside><?php endif;?></div></main></body></html>
